CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM('RESIDENT','GUARD','ADMIN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,role user_role NOT NULL,unit_key text,terminal_id text,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "D1 Visitor Tokens"(token_id uuid PRIMARY KEY,resident_id uuid NOT NULL REFERENCES users(id),visitor_name bytea NOT NULL,visitor_phone bytea NOT NULL,purpose text NOT NULL,valid_from timestamptz NOT NULL,valid_to timestamptz NOT NULL,issued_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',jwt_hash text NOT NULL,signed_token bytea NOT NULL,otp_secret bytea NOT NULL,otp_spent boolean DEFAULT false,entered_at timestamptz,exited_at timestamptz,consent_at timestamptz NOT NULL,consent_version text NOT NULL);
CREATE INDEX IF NOT EXISTS vt_resident_idx ON "D1 Visitor Tokens"(resident_id);CREATE INDEX IF NOT EXISTS vt_status_idx ON "D1 Visitor Tokens"(status);
CREATE TABLE IF NOT EXISTS chain_head(id integer PRIMARY KEY CHECK(id=1),seq bigint NOT NULL DEFAULT 0,hash text NOT NULL);INSERT INTO chain_head VALUES(1,0,repeat('0',64)) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS "D2 Audit Ledger"(entry_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seq bigint UNIQUE NOT NULL,token_id uuid,actor_id uuid NOT NULL,event_type text NOT NULL,is_override boolean DEFAULT false,justification text,timestamp timestamptz NOT NULL,prev_hash text NOT NULL,hash text NOT NULL);
CREATE INDEX IF NOT EXISTS ledger_seq_idx ON "D2 Audit Ledger"(seq);CREATE INDEX IF NOT EXISTS ledger_time_idx ON "D2 Audit Ledger"(timestamp);
CREATE OR REPLACE FUNCTION reject_ledger_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'D2 Audit Ledger is append-only'; END $$;DROP TRIGGER IF EXISTS ledger_no_update ON "D2 Audit Ledger";CREATE TRIGGER ledger_no_update BEFORE UPDATE OR DELETE ON "D2 Audit Ledger" FOR EACH ROW EXECUTE FUNCTION reject_ledger_change();
CREATE TABLE IF NOT EXISTS alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),severity text NOT NULL,message text NOT NULL,created_at timestamptz DEFAULT now());CREATE TABLE IF NOT EXISTS ledger_checkpoints(seq bigint PRIMARY KEY,hash text NOT NULL,signature text NOT NULL);CREATE TABLE IF NOT EXISTS integrity_status(id integer PRIMARY KEY,intact boolean NOT NULL,broken_seq bigint,checked_at timestamptz DEFAULT now());
DO $$ BEGIN CREATE ROLE visitvault_writer NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;DO $$ BEGIN CREATE ROLE visitvault_admin_reader NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;DO $$ BEGIN CREATE ROLE visitvault_retention NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;REVOKE UPDATE,DELETE,TRUNCATE ON "D2 Audit Ledger" FROM PUBLIC,visitvault_writer,visitvault_admin_reader,visitvault_retention;GRANT SELECT,INSERT ON "D2 Audit Ledger" TO visitvault_writer;GRANT SELECT ON "D2 Audit Ledger" TO visitvault_admin_reader;
